1	//! Error types shared by workflow and activity histories.
2	
3	use serde::{Deserialize, Serialize};
4	
5	use crate::Payload;
6	
7	/// Classification for an activity failure.
8	#[derive(Serialize, Deserialize, ts_rs::TS, Clone, Debug, PartialEq, Eq)]
9	pub enum ActivityErrorKind {
10	    /// The activity failure may be retried according to the activity's retry policy.
11	    Retryable,
12	    /// The provider declined the activity under policy; the engine must route it
13	    /// before considering any configured same-provider retry.
14	    PolicyRefused,
15	    /// The activity failure is terminal and must not be retried.
16	    Terminal,
17	}
18	
19	/// Failure reported by an activity execution.
20	///
21	/// The engine consults [`ActivityError::is_retryable`] to decide whether to
22	/// apply the activity's retry policy or fail the workflow.
23	#[derive(Serialize, Deserialize, ts_rs::TS, Clone, Debug, PartialEq, Eq, thiserror::Error)]
24	#[error("{message}")]
25	pub struct ActivityError {
26	    /// Explicit retryability classification for this activity failure.
27	    pub kind: ActivityErrorKind,
28	    /// Human-readable error message.
29	    pub message: String,
30	    /// Optional structured details carried as an opaque payload.
31	    pub details: Option<Payload>,
32	}
33	
34	impl ActivityError {
35	    /// Returns whether the engine may retry this activity failure.
36	    #[must_use]
37	    pub fn is_retryable(&self) -> bool {
38	        matches!(self.kind, ActivityErrorKind::Retryable)
39	    }
40	}
41	
42	/// Terminal failure reported by a workflow execution.
43	#[derive(Serialize, Deserialize, ts_rs::TS, Clone, Debug, PartialEq, Eq, thiserror::Error)]
44	#[error("{message}")]
45	pub struct WorkflowError {
46	    /// Human-readable error message.
47	    pub message: String,
48	    /// Optional structured details carried as an opaque payload.
49	    pub details: Option<Payload>,
50	}
51	
52	impl From<ActivityError> for WorkflowError {
53	    fn from(error: ActivityError) -> Self {
54	        Self {
55	            message: error.message,
56	            details: error.details,
57	        }
58	    }
59	}
60	
61	#[cfg(test)]
62	mod tests {
63	    use serde_json::json;
64	
65	    use super::{ActivityError, ActivityErrorKind, WorkflowError};
66	    use crate::Payload;
67	
68	    #[test]
69	    fn activity_error_reports_retryable_classification() {
70	        let error = ActivityError {
71	            kind: ActivityErrorKind::Retryable,
72	            message: String::from("temporary outage"),
73	            details: None,
74	        };
75	
76	        assert!(error.is_retryable());
77	    }
78	
79	    #[test]
80	    fn activity_error_reports_terminal_classification() {
81	        let error = ActivityError {
82	            kind: ActivityErrorKind::Terminal,
83	            message: String::from("invalid request"),
84	            details: None,
85	        };
86	
87	        assert!(!error.is_retryable());
88	    }
89	
90	    #[test]
91	    fn errors_round_trip_through_json() -> Result<(), Box<dyn std::error::Error>> {
92	        let activity_error = ActivityError {
93	            kind: ActivityErrorKind::Retryable,
94	            message: String::from("connection reset"),
95	            details: Some(Payload::from_json(&json!({"retry_after_ms": 500}))?),
96	        };
97	        let json = serde_json::to_string(&activity_error)?;
98	        let decoded: ActivityError = serde_json::from_str(&json)?;
99	        assert_eq!(activity_error, decoded);
