247	pub(super) async fn dispatch_with_retries(
248	    dispatcher: &Arc<dyn ActivityDispatcher>,
249	    seam: &RetryRecorderSeam,
250	    request: &ActivityDispatch,
251	) -> RetryLoopOutcome {
252	    use super::nif_activity_retry::{activity_timeout_from_config, retry_policy_from_config};
253	
254	    let policy = retry_policy_from_config(&request.config);
255	    // #223: the AUTHORED per-attempt bound, or `None` for unbounded. The
256	    // engine imposes no deadline of its own — an activity whose document
257	    // declares no `timeout` waits exactly as long as it always has.
258	    let bound = activity_timeout_from_config(&request.config);
259	    let mut attempt = request.attempt;
260	    loop {
261	        let mut delivery = request.clone();
262	        delivery.attempt = attempt;
263	        let (reason, expired) = match deliver_one_attempt(dispatcher, delivery, bound).await {
264	            Ok(payload) => return dispatch_completed(attempt, payload),
265	            Err(failure) => failure,
266	        };
267	        // TRANSPORT-domain worker loss: the activity never executed to a result,
268	        // so it is re-dispatched at the SAME attempt with NOTHING recorded —
269	        // attempt-neutral. The prior behaviour delivered this as a terminal
270	        // failure whenever the activity carried no authored retry policy (the
271	        // SDK's run-exactly-once default), so every infrastructure death read to
272	        // the operator as a red action.
273	        //
274	        // The loop cannot spin: the re-dispatch goes through the same
275	        // unserved-queue park a first dispatch does, so it waits for a worker
276	        // rather than failing fast, and the server stops sending this class once
277	        // its transport-loss budget is spent (a `transport-exhausted:` reason
278	        // that no arm here recognises, so it falls through to the terminal
279	        // below). A terminal recorded elsewhere mid-loop still wins — checked
280	        // before every re-dispatch, because this arm records nothing and would
281	        // otherwise never notice.
282	        if super::nif_activity_retry::is_worker_lost_reason(&reason) {
283	            match worker_loss_stand_down(seam, request, &reason, attempt).await {
284	                Some(terminal) => return RetryLoopOutcome { attempt, terminal },
285	                None => continue,
286	            }
287	        }
288	        if let Some(terminal) = failure_stand_down(policy.as_ref(), &reason, attempt, expired) {
289	            if matches!(terminal, RetryLoopTerminal::Failed(_)) {
290	                record_advisory_exhaustion(seam, request, &reason, attempt).await;
291	            }
292	            return RetryLoopOutcome { attempt, terminal };
293	        }
294	        // The stand-down above returns `Failed` whenever no policy is present,
295	        // so a `None` here is structurally unreachable — kept as the honest
296	        // failure terminal rather than an unwrap.
297	        let Some(policy) = policy.as_ref() else {
298	            return RetryLoopOutcome {
299	                attempt,
300	                terminal: RetryLoopTerminal::Failed(reason),
301	            };
302	        };
303	        // Record the failed attempt durably as a NON-terminal (Retryable)
304	        // `ActivityFailed` — the observable retry record the history cursor
305	        // walks past to the eventual terminal. Recording failures abort the
306	        // loop into an honest terminal failure: an unrecorded retry is a
307	        // silent retry.
308	        match record_retry_event(
309	            seam,
310	            request,
311	            RetryRecord::AttemptFailed {
312	                attempt,
313	                reason: reason.clone(),
314	            },
315	        )
316	        .await
317	        {
318	            RetryRecordOutcome::Recorded => {}
319	            RetryRecordOutcome::Settled => {
320	                return RetryLoopOutcome {
321	                    attempt,
322	                    terminal: RetryLoopTerminal::SettledElsewhere,
323	                };
324	            }
325	            RetryRecordOutcome::EpochClosed => {
326	                return stood_down_on_closed_epoch(request, attempt);
327	            }
328	            RetryRecordOutcome::RecordFailed(record_error) => {
329	                tracing::warn!(
330	                    workflow_id = %request.workflow_id,
331	                    activity_id = %request.activity_id,
332	                    attempt,
333	                    error = %record_error,
334	                    "failed to record a retryable activity failure; failing the activity instead \
335	                     of retrying unrecorded"
336	                );
337	                return RetryLoopOutcome {
338	                    attempt,
339	                    terminal: RetryLoopTerminal::Failed(reason),
340	                };
341	            }
342	        }
343	        announce_and_back_off(policy, request, &reason, attempt).await;
344	        attempt += 1;
345	        // Record the retry delivery's `ActivityStarted` before it goes on the
346	        // wire, so history and the worker wire agree on the attempt (NOI-0) —
347	        // re-guarded, because the backoff sleep is a settle-race window.
348	        match record_retry_event(seam, request, RetryRecord::AttemptStarted { attempt }).await {
349	            RetryRecordOutcome::Recorded => {}
350	            RetryRecordOutcome::Settled => {
351	                return RetryLoopOutcome {
352	                    attempt,
353	                    terminal: RetryLoopTerminal::SettledElsewhere,
354	                };
355	            }
356	            RetryRecordOutcome::EpochClosed => {
357	                return stood_down_on_closed_epoch(request, attempt);
358	            }
359	            RetryRecordOutcome::RecordFailed(record_error) => {
360	                tracing::warn!(
361	                    workflow_id = %request.workflow_id,
362	                    activity_id = %request.activity_id,
363	                    attempt,
364	                    error = %record_error,
365	                    "failed to record a retry attempt start; failing the activity instead of \
366	                     dispatching unrecorded"
367	                );
368	                return RetryLoopOutcome {
369	                    attempt,
370	                    terminal: RetryLoopTerminal::Failed(reason),
371	                };
372	            }
373	        }
374	    }
375	}
376	
377	/// Announce a retryable action failure and sleep out its backoff before the next
378	/// attempt goes on the wire.
379	///
380	/// Split out of the loop body purely for size; the sleep is deliberately
381	/// task-local rather than a durable timer (an engine crash mid-backoff recovers
382	/// through replay, whose dangling retryable failure re-dispatches live).
383	async fn announce_and_back_off(
384	    policy: &super::nif_activity_retry::RetryPolicy,
385	    request: &ActivityDispatch,
386	    reason: &str,
387	    attempt: u32,
388	) {
389	    let delay = policy.backoff.delay_after(attempt);
390	    tracing::warn!(
391	        workflow_id = %request.workflow_id,
392	        activity_id = %request.activity_id,
393	        activity_type = %request.name,
394	        attempt,
395	        max_attempts = policy.max_attempts,
396	        retry_in_ms = u64::try_from(delay.as_millis()).unwrap_or(u64::MAX),
397	        reason = %reason,
398	        "activity attempt failed with a retryable error; re-dispatching"
399	    );
400	    tokio::time::sleep(delay).await;
401	}
402	
403	/// Decide what an attempt-neutral worker-loss re-dispatch does: stand the loop
404	/// down when the ordinal was settled elsewhere, or `None` to re-dispatch the
405	/// SAME attempt, recording nothing.
406	///
407	/// The settlement read is load-bearing precisely BECAUSE this path records
408	/// nothing: every other arm of the loop rides `record_retry_event`'s settlement
409	/// check, and without this one a re-dispatch could outlive a `with_timeout`
410	/// expiry (or a workflow terminal) that already decided the ordinal.
411	async fn worker_loss_stand_down(
412	    seam: &RetryRecorderSeam,
413	    request: &ActivityDispatch,
414	    reason: &str,
415	    attempt: u32,
416	) -> Option<RetryLoopTerminal> {
417	    if activity_settled_elsewhere(seam, request).await {
418	        return Some(RetryLoopTerminal::SettledElsewhere);
419	    }
420	    tracing::warn!(
421	        workflow_id = %request.workflow_id,
422	        activity_id = %request.activity_id,
423	        activity_type = %request.name,
424	        attempt,
425	        reason = %reason,
426	        "activity's worker was lost before it reported a result; re-dispatching the same \
427	         attempt (transport loss consumes no authored retry budget)"
428	    );
429	    None
430	}
431	
432	/// Whether this ordinal (within its run) already carries a recorded terminal.
433	///
434	/// The attempt-neutral worker-loss re-dispatch records NOTHING, so it has no
435	/// `record_retry_event` settle check to ride on; without this read it could
436	/// re-dispatch an ordinal a `with_timeout` expiry (or a workflow terminal)
437	/// already settled. A read failure answers `false` — the loop then re-dispatches
438	/// and the recorder's own guards still refuse a post-terminal append, which is
439	/// strictly safer than standing an activity down on an unreadable history.
440	async fn activity_settled_elsewhere(seam: &RetryRecorderSeam, request: &ActivityDispatch) -> bool {
441	    let recorder = seam.recorder.lock().await;
442	    let Ok(history) = recorder.read_history().await else {
443	        return false;
444	    };
445	    let Ok(history) = crate::durability::current_run_segment(history, &seam.run_id) else {
446	        return false;
447	    };
448	    super::nif_activity_retry::activity_settled(&history, &request.activity_id)
449	}
450	
451	/// Record the R5 warning when an ADVISORY activity's attempt budget is spent
452	/// (RUNTIME-OPERATIONS.md R5).
453	///
454	/// "Retry exhaustion" is read as the attempt budget being SPENT, whatever its
455	/// size: an advisory action with no declared retry has a budget of one, and its
456	/// single failure exhausts it exactly as a declared `retry 5` exhausts five.
457	/// The warning therefore fires on every terminal failure of an advisory
458	/// dispatch, and never on a park or a settled-elsewhere stand-down (neither is
459	/// a failure, and both must record nothing).
460	///
461	/// Ordering: the warning lands JUST BEFORE the failure is delivered, so it
462	/// precedes the terminal `ActivityFailed` the workflow thread records on
463	/// receipt. Both are in history; the warning never replaces the failure.
464	///
465	/// A recording failure here is logged and swallowed — deliberately. The
466	/// activity's own honest terminal is what the workflow acts on; losing the
467	/// warning must not also change the outcome the run gets.
468	async fn record_advisory_exhaustion(
469	    seam: &RetryRecorderSeam,
470	    request: &ActivityDispatch,
471	    reason: &str,
472	    attempt: u32,
473	) {
474	    if !request.advisory {
475	        return;
476	    }
477	    match record_retry_event(
478	        seam,
479	        request,
480	        RetryRecord::AdvisoryExhausted {
481	            attempt,
482	            reason: reason.to_owned(),
483	        },
484	    )
485	    .await
486	    {
487	        RetryRecordOutcome::Recorded | RetryRecordOutcome::Settled => {}
488	        // Advisory only, so there is nothing to fail — but it is still not the
489	        // same event as `Settled`, and a reader of these logs must be able to
490	        // tell "somebody else finished it" from "we stopped being the writer".
491	        RetryRecordOutcome::EpochClosed => {
492	            tracing::info!(
493	                workflow_id = %request.workflow_id,
494	                activity_id = %request.activity_id,
495	                attempt,
496	                "engine task epoch closed before the advisory exhaustion note could be recorded"

497	            );
498	        }
499	        RetryRecordOutcome::RecordFailed(record_error) => {
500	            tracing::warn!(
501	                workflow_id = %request.workflow_id,
502	                activity_id = %request.activity_id,
503	                attempt,
504	                error = %record_error,
505	                "failed to record the advisory-exhaustion warning; the activity's terminal \
506	                 failure still stands"
507	            );
508	        }
509	    }
510	}
511	
512	/// One durable retry record the loop appends between attempts.
513	enum RetryRecord {
514	    /// The just-failed attempt's non-terminal `ActivityFailed`.
515	    AttemptFailed { attempt: u32, reason: String },
516	    /// The next delivery's `ActivityStarted`.
517	    AttemptStarted { attempt: u32 },
518	    /// The R5 warning that an ADVISORY activity spent its attempt budget.
519	    AdvisoryExhausted { attempt: u32, reason: String },
520	}
521	
522	enum RetryRecordOutcome {
523	    Recorded,
524	    /// The ordinal (or workflow) already has a recorded terminal; the loop
525	    /// must stop without recording or delivering anything further.
526	    Settled,
527	    /// This engine's task epoch closed before the append could land, so this
528	    /// process is no longer the run's single writer. Distinct from [`Settled`]
529	    /// on purpose: nothing was recorded by anyone, the run is simply not ours
530	    /// to write for any more, and the two must not be reported as one thing.
531	    EpochClosed,
532	    RecordFailed(crate::durability::DurabilityError),
533	}
534	
535	/// Append one retry record under the recorder lock, re-checking settlement
536	/// first so the append can never land after a terminal recorded by the
537	/// workflow thread (`with_timeout` expiry, workflow terminal).
538	async fn record_retry_event(
539	    seam: &RetryRecorderSeam,
540	    request: &ActivityDispatch,
541	    record: RetryRecord,
542	) -> RetryRecordOutcome {
543	    let mut recorder = seam.recorder.lock().await;
544	    // 🔴 THE EPOCH GATE, UNDER THE RECORDER LOCK. This is the last point at
545	    // which this process can still decline to be a second writer: after it,
546	    // the append is issued. Checking here rather than at spawn or between
547	    // attempts is the same argument `EngineTaskRuntime::is_epoch_open` makes
548	    // about itself — an earlier check can be walked past, because the attempt
549	    // that passed it goes on to hold the engine open across a history read, a
550	    // lock acquisition and a store round-trip before it writes anything.
551	    //
552	    // Refusing is the safe direction: nothing is lost that the owning engine
553	    // cannot re-derive. The activity's durable trail simply ends where this
554	    // process stopped being its writer, which is byte-equivalent to a
555	    // `kill -9` at the same instant — the shape the parking path below is
556	    // already built for.
557	    if !seam.engine_tasks.is_epoch_open() {
558	        return RetryRecordOutcome::EpochClosed;
559	    }
560	    let history = match recorder.read_history().await {
561	        Ok(history) => history,
562	        Err(error) => return RetryRecordOutcome::RecordFailed(error),
563	    };
564	    // Settlement is a per-run question: scope to the current run's segment so
565	    // a prior run's terminal (continue-as-new) never aborts this run's loop.
566	    let history = match crate::durability::current_run_segment(history, &seam.run_id) {
567	        Ok(history) => history,
568	        Err(error) => return RetryRecordOutcome::RecordFailed(error),
569	    };
570	    if super::nif_activity_retry::activity_settled(&history, &request.activity_id) {
571	        return RetryRecordOutcome::Settled;
572	    }
573	    let append_result = match record {
574	        RetryRecord::AttemptFailed { attempt, reason } => {
575	            recorder
576	                .record_activity_failed(
577	                    chrono::Utc::now(),
578	                    request.activity_id.clone(),
579	                    aion_core::ActivityError {
580	                        kind: aion_core::ActivityErrorKind::Retryable,
581	                        message: reason,
582	                        details: None,
583	                    },
584	                    attempt,
585	                )
586	                .await
587	        }
588	        RetryRecord::AttemptStarted { attempt } => {
589	            recorder
590	                .record_activity_started(chrono::Utc::now(), request.activity_id.clone(), attempt)
591	                .await
592	        }
593	        RetryRecord::AdvisoryExhausted { attempt, reason } => {
594	            recorder
595	                .record_activity_advisory_exhausted(
596	                    chrono::Utc::now(),
597	                    request.activity_id.clone(),
598	                    request.name.clone(),
599	                    reason,
600	                    attempt,
601	                )
602	                .await
603	        }
604	    };
605	    match append_result {
606	        Ok(()) => RetryRecordOutcome::Recorded,
607	        Err(error) => RetryRecordOutcome::RecordFailed(error),
608	    }
609	}

320	
321	/// Whether the activity (or its whole workflow) already reached a terminal
322	/// recorded outcome, so an in-flight retry loop must stop recording.
323	///
324	/// Guards the completion task's durable retry records against the settle
325	/// races the workflow thread can win while a retry sleeps or dispatches: a
326	/// `with_timeout` scope expiry records a terminal `ActivityFailed` for the
327	/// awaited ordinal, and a workflow terminal ends the run outright. Recording
328	/// a retry attempt AFTER such a terminal would make the replay walk read the
329	/// terminal as superseded — so the loop re-checks this under the recorder
330	/// lock before every append and aborts when the decision was already made.
331	///
332	/// Scans NEWEST-first because reopen supersedes terminals: a
333	/// [`Event::WorkflowReopened`] naming this activity re-drives it live, so the
334	/// most recent decisive event — the activity's own terminal, a workflow
335	/// terminal, or the reopen that supersedes them — wins.
336	pub(super) fn activity_settled(history: &[Event], activity_id: &ActivityId) -> bool {
337	    for event in history.iter().rev() {
338	        match event {
339	            Event::ActivityCompleted {
340	                activity_id: id, ..
341	            }
342	            | Event::ActivityCancelled {
343	                activity_id: id, ..
344	            } if id == activity_id => return true,
345	            Event::ActivityFailed {
346	                activity_id: id,
347	                error,
348	                ..
349	            } if id == activity_id && !error.is_retryable() => return true,
350	            Event::WorkflowReopened { reopened, .. } if reopened.contains(activity_id) => {
351	                // The reopen supersedes every prior terminal for this
352	                // activity AND the workflow terminal it belonged to; the
353	                // activity is live again.
354	                return false;
355	            }
356	            Event::WorkflowCompleted { .. }
357	            | Event::WorkflowFailed { .. }
358	            | Event::WorkflowCancelled { .. }
359	            | Event::WorkflowTimedOut { .. }
360	            | Event::WorkflowContinuedAsNew { .. } => return true,
361	            _ => {}
362	        }
363	    }
364	    false
365	}
366	
367	/// The recorded reason a recovery re-dispatch stamps onto an ORDINARY
368	/// activity's dangling attempt: the prior server died with this attempt in
369	/// flight and nothing else will ever settle it (#266 Defect B).
370	///
371	/// The record is written with `ActivityErrorKind::Retryable` — NON-terminal —
372	/// and is an HONESTY record, not a budget event (ruled 2026-08-17,
373	/// honesty-only): infrastructure death is attempt-neutral at the budget layer,
374	/// exactly as [`is_worker_lost_reason`]'s arm treats a worker dying
375	/// mid-attempt, so re-dispatch proceeds unconditionally and the history cursor
376	/// walks past this record exactly as it walks past a live retry record (#197).
377	/// Terminality by retry policy governs action-authored failures only.
378	///
379	/// It is NOT written for a declared AGENT action: that holder can outlive the
380	/// engine by construction, so the same sentence about it would be a lie about
381	/// live work (#36). See `super::nif_activity_agent` for the fork.
382	pub(super) const SUPERSEDED_BY_SERVER_DEATH_REASON: &str = "superseded:server-death";
383	
384	/// The dangling attempt a recovery re-dispatch has to account for, or `None`
385	/// when there is nothing dangling.
386	///
387	/// ONE detector, TWO consumers, because they are asking the same question and
388	/// must never disagree about the answer: an ordinary activity's dangling
389	/// attempt is SUPERSEDED (#266 Defect B) and an agent's is OFFERED FOR
390	/// ADOPTION (#36). What differs is what gets recorded and whether the attempt
391	/// identity is retained — not which attempt is dangling.
392	///
393	/// `Some(n)` exactly when the ordinal's highest recorded attempt `n` has an
394	/// [`Event::ActivityStarted`] and NO settling record of its own — no
395	/// [`Event::ActivityFailed`], [`Event::ActivityCompleted`], or
396	/// [`Event::ActivityCancelled`] at attempt `n`. An already-settled attempt is
397	/// not adoptable; a fresh ordinal has no identity to adopt; and a
398	/// Scheduled-with-no-Started trail carries no attempt number at all.
399	pub(super) fn dangling_attempt(history: &[Event], activity_id: &ActivityId) -> Option<u32> {
400	    let latest = latest_recorded_attempt(history, activity_id)?;
401	    let mut started = false;
402	    for event in history {
403	        match event {
404	            Event::ActivityStarted {
405	                activity_id: id,
406	                attempt,
407	                ..
408	            } if id == activity_id && *attempt == latest => started = true,
409	            Event::ActivityFailed {
410	                activity_id: id,
411	                attempt,
412	                ..
413	            }
414	            | Event::ActivityCompleted {
415	                activity_id: id,
416	                attempt,
417	                ..
418	            }
419	            | Event::ActivityCancelled {
420	                activity_id: id,
421	                attempt,
422	                ..
423	            } if id == activity_id && *attempt == latest => return None,
424	            _ => {}
425	        }
426	    }
427	    started.then_some(latest)
428	}
429	
430	/// The one-based attempt the NEXT live delivery of `activity_id` must carry,
431	/// derived from recorded history.
432	///
433	/// A fresh ordinal (no recorded attempts) is [`FIRST_DELIVERY_ATTEMPT`]. A
434	/// crash-recovery re-dispatch after a dangling retryable failure — recorded
435	/// attempt trail with no terminal — continues the trail instead of reusing an
436	/// attempt number, keeping `(workflow, activity, attempt)` a stable identity
437	/// across the restart. Legacy histories whose events decode the `attempt`
438	/// sentinel (`0`) resolve to [`FIRST_DELIVERY_ATTEMPT`] deterministically.
439	pub(super) fn next_delivery_attempt(history: &[Event], activity_id: &ActivityId) -> u32 {
440	    latest_recorded_attempt(history, activity_id).map_or(FIRST_DELIVERY_ATTEMPT, |attempt| {
