        tracing::warn!(fallback = %fallback, "malformed activity fallback chain; expected an array of queue names");
        return Vec::new();
    };
    let chain = entries
        .iter()
        .map(|entry| entry.as_str().map(str::to_owned))
        .collect::<Option<Vec<_>>>();
