+/// The latest event for this activity is a nonterminal policy refusal, meaning
+/// recovery must finish the hop/retry decision before recording another start.
+pub(super) fn trailing_policy_refusal(
+    history: &[Event],
+    activity_id: &ActivityId,
+) -> Option<(u32, String)> {
+    history.iter().rev().find_map(|event| match event {
+        Event::ActivityFailed {
