+                Some((*attempt, error.message.clone()))
+            } else {
+                None
+            }
+        }
+        Event::ActivityStarted { activity_id: id, .. }
+        | Event::ActivityCompleted { activity_id: id, .. }
+        | Event::ActivityCancelled { activity_id: id, .. }
+            if id == activity_id => None,
+        _ => None,
+    })
+}
