1	//! History-derived activity fallback routing.
2	
3	use aion_core::{ActivityId, Event};
4	
5	/// Decode the authored fallback queue chain from one activity dispatch config.
6	///
7	/// The config is emitted by the BEAM module bound to this run, not read from the
8	/// currently deployed package. Every `.aion` version is an immutable,
9	/// content-hash-named module and recovery re-executes workflow code from that
10	/// bound module, so the authored list is stable for the run. Reading a current
11	/// deployment instead would agree in ordinary tests but break replay for a
12	/// long-lived workflow when a different list is deployed mid-hop.
13	///
14	/// Routing metadata never makes dispatch decoding fail. An absent or explicit
15	/// `null` field means no chain; malformed JSON or a present value that is not an
16	/// array of strings is warned about and treated as no chain.
17	pub(super) fn fallback_chain_from_config(config: &str) -> Vec<String> {
18	    let value: serde_json::Value = match serde_json::from_str(config) {
19	        Ok(value) => value,
20	        Err(error) => {
21	            tracing::warn!(%error, "malformed activity dispatch config; ignoring fallback routing");
22	            return Vec::new();
23	        }
24	    };
25	    let Some(fallback) = value.get("fallback") else {
26	        return Vec::new();
27	    };
28	    if fallback.is_null() {
29	        return Vec::new();
30	    }
31	    let Some(entries) = fallback.as_array() else {
32	        tracing::warn!(fallback = %fallback, "malformed activity fallback chain; expected an array of queue names");
33	        return Vec::new();
34	    };
35	    let chain = entries
36	        .iter()
37	        .map(|entry| entry.as_str().map(str::to_owned))
38	        .collect::<Option<Vec<_>>>();
39	    match chain {
40	        Some(chain) => chain,
41	        None => {
42	            tracing::warn!(fallback = %fallback, "malformed activity fallback chain; every queue name must be a string");
43	            Vec::new()
44	        }
45	    }
46	}
47	
48	/// Select the first authored queue at or after `consumed` that differs from the
49	/// queue currently serving the activity, preserving its original authored index.
50	pub(super) fn next_hop(
51	    chain: &[String],
52	    initial_queue: &str,
53	    current_queue: &str,
54	    consumed: usize,
55	) -> Option<(usize, String)> {
56	    let effective_current = if current_queue.is_empty() {
57	        initial_queue
58	    } else {
59	        current_queue
60	    };
61	    chain
62	        .iter()
63	        .enumerate()
64	        .skip(consumed)
65	        .find(|(_, queue)| queue.as_str() != effective_current)
66	        .map(|(index, queue)| (index, queue.clone()))
67	}
68	
69	/// Recorded fallback hops for one activity, in durable history order.
70	pub(super) fn recorded_hops<'a>(history: &'a [Event], activity_id: &ActivityId) -> Vec<&'a Event> {
71	    history
72	        .iter()
73	        .filter(|event| {
74	            matches!(
75	                event,
76	                Event::ActivityFallbackRouted {
77	                    activity_id: id,
78	                    ..
79	                } if id == activity_id
80	            )
81	        })
82	        .collect()
83	}
84	
85	/// The latest durably selected fallback queue for one activity.
86	pub(super) fn recorded_hop_queue(history: &[Event], activity_id: &ActivityId) -> Option<String> {
87	    recorded_hops(history, activity_id)
88	        .into_iter()
89	        .rev()
90	        .find_map(|event| match event {
91	            Event::ActivityFallbackRouted { to_task_queue, .. } => Some(to_task_queue.clone()),
92	            _ => None,
93	        })
94	}
95	
96	/// The next authored position after all durably recorded hops.
97	pub(super) fn consumed_fallback_position(history: &[Event], activity_id: &ActivityId) -> usize {
98	    recorded_hops(history, activity_id)
99	        .into_iter()
100	        .filter_map(|event| match event {
101	            Event::ActivityFallbackRouted { fallback_index, .. } => {
102	                usize::try_from(*fallback_index)
103	                    .ok()
104	                    .and_then(|index| index.checked_add(1))
105	            }
106	            _ => None,
107	        })
108	        .max()
109	        .unwrap_or(0)
110	}
111	
112	/// Initial queue followed by each durably recorded hop destination.
113	pub(super) fn refused_queue_sequence(
114	    history: &[Event],
115	    activity_id: &ActivityId,
116	    initial_queue: &str,
117	) -> Vec<String> {
118	    let mut queues = vec![initial_queue.to_owned()];
119	    queues.extend(recorded_hops(history, activity_id).into_iter().filter_map(
120	        |event| match event {
121	            Event::ActivityFallbackRouted { to_task_queue, .. } => Some(to_task_queue.clone()),
122	            _ => None,
123	        },
124	    ));
125	    queues
126	}
127	
128	#[cfg(test)]
129	mod tests {
130	    use super::{fallback_chain_from_config, next_hop};
131	
132	    #[test]
133	    fn fallback_config_accepts_only_string_arrays() {
134	        assert_eq!(
135	            fallback_chain_from_config(r#"{"fallback":["norn","claude"]}"#),
136	            ["norn", "claude"]
137	        );
138	        assert!(fallback_chain_from_config(r#"{"fallback":null}"#).is_empty());
139	        assert!(fallback_chain_from_config(r#"{"fallback":["norn",2]}"#).is_empty());
140	    }
141	
142	    #[test]
143	    fn next_hop_skips_current_queue_but_keeps_authored_index() {
144	        let chain = vec!["norn".to_owned(), "claude".to_owned()];
145	        assert_eq!(
146	            next_hop(&chain, "norn", "norn", 0),
147	            Some((1, "claude".to_owned()))
148	        );
149	        assert_eq!(next_hop(&chain, "norn", "claude", 2), None);
150	    }
151	}

