246	fn open_this_delivery(
247	    ctx: &mut ProcessContext,
248	    context: &NifContext,
249	    catalog: Option<&crate::loader::WorkflowCatalog>,
250	    opening: Opening<'_>,
251	) -> Result<u32, NifRefusal> {
252	    let Opening {
253	        activity_id,
254	        activity_type,
255	        input,
256	        task_queue,
257	        node,
258	        first_delivery_attempt,
259	    } = opening;
260	    let dangling = super::nif_activity_retry::dangling_attempt(context.history(), activity_id);
261	    let adopts = dangling.is_some()
262	        && super::nif_activity_agent::declared_agent(
263	            catalog,
264	            &context.workflow_handle(),
265	            activity_type,
266	        );
267	    match dangling {
268	        Some(dangling) if adopts => {
269	            context
270	                .record_activity_adoption_offered(chrono::Utc::now(), activity_id.clone(), dangling)
271	                .map_err(|error| context_error_term(ctx, &error))?;
272	            Ok(dangling)
273	        }
274	        dangling => {
275	            let attempt =
276	                super::nif_activity_retry::next_delivery_attempt(context.history(), activity_id)
277	                    .max(first_delivery_attempt);
278	            if let Some(superseded) = dangling {
279	                record_superseded_attempt(ctx, context, activity_id, superseded)?;
280	            }
281	            record_started(
282	                ctx,
283	                context,
284	                activity_id.clone(),
285	                super::nif_activity::ScheduledActivity {
286	                    activity_type: activity_type.to_owned(),
287	                    input,
288	                    task_queue: task_queue.to_owned(),
289	                    node: node.map(str::to_owned),
290	                    // NOI-0: stamp the SAME one-based attempt onto the recorded
291	                    // `ActivityStarted` that is stamped onto the live
292	                    // `ActivityDispatch` below, so history and the worker wire agree.
293	                    attempt,
294	                },
295	            )?;
296	            Ok(attempt)
297	        }
298	    }
299	}
300	
301	fn dispatch_activity_with_context(
302	    ctx: &mut ProcessContext,
303	    mut context: NifContext,
304	    dispatcher: Option<Arc<dyn ActivityDispatcher>>,
305	    runtime: Arc<crate::RuntimeHandle>,
306	    tokio_handle: &tokio::runtime::Handle,
307	    catalog: Option<&crate::loader::WorkflowCatalog>,
308	    call: ActivityCall,
309	) -> Result<Term, NifRefusal> {
310	    let input_payload = json_payload(ctx, &call.input, "dispatch_activity", "input")?;
311	    let ordinal = context.next_activity_ordinal();
312	    let key = CorrelationKey::Activity(ordinal);
313	    let activity_id = ActivityId::from_sequence_position(ordinal);
314	    let correlation = correlation_id(ordinal);
315	    let namespace = context.workflow_handle().namespace().to_owned();
316	    // UNOBSERVED seam. The dispatch hands workflow code a correlation id, not
317	    // the activity's outcome — the outcome is delivered by
318	    // `await_activity_result`, which is the OBSERVED seam. Recorded resolution
319	    // here reaches the activity's TERMINAL, which the live path has not reached
320	    // at this position (it has only just recorded `ActivityScheduled`), so
321	    // advancing workflow-visible now here would make a replayed run serve a
322	    // timestamp its live original could not have served (aion#1).
323	    match context
324	        .resolve_command_unobserved(Command::RunActivity {
325	            key,
326	            activity_type: call.name.clone(),
327	            input: input_payload.clone(),
328	        })
329	        .map_err(|error| context_error_term(ctx, &error))?
330	    {
331	        ResolveOutcome::Recorded(_) => {
332	            ok_result_term(ctx, correlation.as_bytes()).map_err(NifRefusal::Unbuildable)
333	        }
334	        ResolveOutcome::ResumeLive => {
335	            let Some(dispatcher) = dispatcher else {
336	                return error_result_term(
337	                    ctx,
338	                    "no activity dispatcher configured — set one via EngineBuilder::activity_dispatcher",
339	                )
340	                .map_err(NifRefusal::Unbuildable);
341	            };
342	            // NSTQ-4 (+#144): resolve the dispatch's task queue once at this
343	            // schedule seam (activity override > workflow declared default >
344	            // the workflow's RECORDED start-time queue > the named default),
345	            // then stamp the same value onto BOTH the recorded
346	            // `ActivityScheduled` and the live dispatch so history and routing
347	            // never diverge. The start-time queue is read from recorded history,
348	            // so replay re-resolves identically.
349	            let start_time_task_queue = context.start_time_task_queue();
350	            let initial_task_queue = super::nif_activity::resolve_task_queue(
351	                &call.config,
352	                start_time_task_queue.as_deref(),
353	            );
354	            // A recorded hop is a post-failure override of the initial choice,
355	            // not another precedence level inside `resolve_task_queue`. Reading
356	            // the durable answer makes crash recovery reuse the selected queue.
357	            let task_queue =
358	                super::nif_activity_fallback::recorded_hop_queue(context.history(), &activity_id)
359	                    .unwrap_or(initial_task_queue);
360	            // NODE-4: resolve the OPTIONAL node affinity once at the same seam
361	            // (activity pin, else None — no workflow default), and stamp the same
362	            // value onto BOTH the recorded `ActivityScheduled` and the live
363	            // dispatch so history and routing never diverge.
364	            let node = super::nif_activity::resolve_node(&call.config);
365	            let attempt = open_this_delivery(
366	                ctx,
367	                &context,
368	                catalog,
369	                Opening {
370	                    activity_id: &activity_id,
371	                    activity_type: &call.name,
372	                    input: input_payload,
373	                    task_queue: &task_queue,
374	                    node: node.as_deref(),
375	                    first_delivery_attempt: call.attempt,

250	}
251	
252	/// Drive one activity dispatch to its final outcome under the SDK-declared
253	/// retry policy and per-attempt timeout carried in the dispatch config
254	/// (#197, #223).
255	pub(super) async fn dispatch_with_retries(
256	    dispatcher: &Arc<dyn ActivityDispatcher>,
257	    seam: &RetryRecorderSeam,
258	    request: &ActivityDispatch,
259	) -> RetryLoopOutcome {
260	    use super::nif_activity_retry::{activity_timeout_from_config, retry_policy_from_config};
261	
262	    let policy = retry_policy_from_config(&request.config);
263	    let fallback_chain = super::nif_activity_fallback::fallback_chain_from_config(&request.config);
264	    let history = retry_history(seam).await.unwrap_or_default();
265	    let initial_queue = request.task_queue.clone();
266	    let mut current_queue =
267	        super::nif_activity_fallback::recorded_hop_queue(&history, &request.activity_id)
268	            .unwrap_or_else(|| initial_queue.clone());
269	    let mut consumed_fallback =
270	        super::nif_activity_fallback::consumed_fallback_position(&history, &request.activity_id);
271	    let recorded_hops = super::nif_activity_fallback::recorded_hops(&history, &request.activity_id);
272	    let hop_count = u32::try_from(recorded_hops.len()).unwrap_or(u32::MAX);
273	    let mut refused_queues = super::nif_activity_fallback::refused_queue_sequence(
274	        &history,
275	        &request.activity_id,
276	        &initial_queue,
277	    );
278	    // #223: the AUTHORED per-attempt bound, or `None` for unbounded. The
279	    // engine imposes no deadline of its own — an activity whose document
280	    // declares no `timeout` waits exactly as long as it always has.
281	    let bound = activity_timeout_from_config(&request.config);
282	    let mut attempt = request.attempt;
283	    let mut same_provider_attempt = attempt.saturating_sub(hop_count).max(1);
284	    loop {
285	        let mut delivery = request.clone();
286	        delivery.attempt = attempt;
287	        delivery.task_queue = current_queue.clone();
288	        let (reason, expired) = match deliver_one_attempt(dispatcher, delivery, bound).await {
289	            Ok(payload) => return dispatch_completed(attempt, payload),
290	            Err(failure) => failure,
291	        };
292	        // TRANSPORT-domain worker loss: the activity never executed to a result,
293	        // so it is re-dispatched at the SAME attempt with NOTHING recorded —
294	        // attempt-neutral. The prior behaviour delivered this as a terminal
295	        // failure whenever the activity carried no authored retry policy (the
296	        // SDK's run-exactly-once default), so every infrastructure death read to
297	        // the operator as a red action.
298	        //
299	        // The loop cannot spin: the re-dispatch goes through the same
300	        // unserved-queue park a first dispatch does, so it waits for a worker
301	        // rather than failing fast, and the server stops sending this class once
302	        // its transport-loss budget is spent (a `transport-exhausted:` reason
303	        // that no arm here recognises, so it falls through to the terminal
304	        // below). A terminal recorded elsewhere mid-loop still wins — checked
305	        // before every re-dispatch, because this arm records nothing and would
306	        // otherwise never notice.
307	        if super::nif_activity_retry::is_worker_lost_reason(&reason) {
308	            match worker_loss_stand_down(seam, request, &reason, attempt).await {
309	                Some(terminal) => return RetryLoopOutcome { attempt, terminal },
310	                None => continue,
311	            }
312	        }
313	        let policy_refused = super::nif_activity_retry::is_policy_refused_reason(&reason);
314	        if policy_refused {
315	            match record_retry_event(
316	                seam,
317	                request,
318	                RetryRecord::AttemptFailed {
319	                    attempt,
320	                    reason: reason.clone(),
321	                    kind: aion_core::ActivityErrorKind::PolicyRefused,
322	                },
323	            )
324	            .await
325	            {
326	                RetryRecordOutcome::Recorded => {}
327	                RetryRecordOutcome::Settled => {
328	                    return RetryLoopOutcome {
329	                        attempt,
330	                        terminal: RetryLoopTerminal::SettledElsewhere,
331	                    };
332	                }
333	                RetryRecordOutcome::EpochClosed => {
334	                    return stood_down_on_closed_epoch(request, attempt);
335	                }
336	                RetryRecordOutcome::RecordFailed(record_error) => {
337	                    tracing::warn!(
338	                        workflow_id = %request.workflow_id,
339	                        activity_id = %request.activity_id,
340	                        attempt,
341	                        error = %record_error,
342	                        "failed to record a policy refusal; failing instead of routing unrecorded"
343	                    );
344	                    return RetryLoopOutcome {
345	                        attempt,
346	                        terminal: RetryLoopTerminal::Failed(reason),
347	                    };
348	                }
349	            }
350	
351	            if !fallback_chain.is_empty() {
352	                if let Some((fallback_index, next_queue)) = super::nif_activity_fallback::next_hop(
353	                    &fallback_chain,
354	                    &initial_queue,
355	                    &current_queue,
356	                    consumed_fallback,
357	                ) {
358	                    let fallback_index_u32 = u32::try_from(fallback_index).unwrap_or(u32::MAX);
359	                    match record_retry_event(
360	                        seam,
361	                        request,
362	                        RetryRecord::FallbackRouted {
363	                            attempt,
364	                            from_task_queue: current_queue.clone(),
365	                            to_task_queue: next_queue.clone(),
366	                            fallback_index: fallback_index_u32,
367	                        },
368	                    )
369	                    .await
370	                    {
371	                        RetryRecordOutcome::Recorded => {}
372	                        RetryRecordOutcome::Settled => {
373	                            return RetryLoopOutcome {
374	                                attempt,
375	                                terminal: RetryLoopTerminal::SettledElsewhere,
376	                            };
377	                        }
378	                        RetryRecordOutcome::EpochClosed => {
379	                            return stood_down_on_closed_epoch(request, attempt);
380	                        }
381	                        RetryRecordOutcome::RecordFailed(record_error) => {
382	                            tracing::warn!(
383	                                workflow_id = %request.workflow_id,
384	                                activity_id = %request.activity_id,
385	                                attempt,
386	                                error = %record_error,
387	                                "failed to record a fallback hop; failing instead of routing unrecorded"
388	                            );
389	                            return RetryLoopOutcome {
390	                                attempt,
391	                                terminal: RetryLoopTerminal::Failed(reason),
392	                            };
393	                        }
394	                    }
395	                    consumed_fallback = fallback_index.saturating_add(1);
396	                    current_queue = next_queue;
397	                    refused_queues.push(current_queue.clone());
398	                    attempt = attempt.saturating_add(1);
399	                    match record_retry_event(seam, request, RetryRecord::AttemptStarted { attempt })
400	                        .await
401	                    {
402	                        RetryRecordOutcome::Recorded => continue,
403	                        RetryRecordOutcome::Settled => {
404	                            return RetryLoopOutcome {
405	                                attempt,
406	                                terminal: RetryLoopTerminal::SettledElsewhere,
407	                            };
408	                        }
409	                        RetryRecordOutcome::EpochClosed => {
410	                            return stood_down_on_closed_epoch(request, attempt);
411	                        }
412	                        RetryRecordOutcome::RecordFailed(record_error) => {
413	                            tracing::warn!(
414	                                workflow_id = %request.workflow_id,
415	                                activity_id = %request.activity_id,
416	                                attempt,
417	                                error = %record_error,
418	                                "failed to record a fallback attempt start; failing instead of \
419	                                 dispatching unrecorded"
420	                            );
421	                            return RetryLoopOutcome {
422	                                attempt,
423	                                terminal: RetryLoopTerminal::Failed(reason),
424	                            };
425	                        }
426	                    }
427	                }
428	                return RetryLoopOutcome {
429	                    attempt,
430	                    terminal: RetryLoopTerminal::Failed(format!(
431	                        "policy_refused: declared fallback queues refused in recorded order: {}",
432	                        refused_queues.join(", ")
433	                    )),
434	                };
435	            }
436	        }
437	        if let Some(terminal) = failure_stand_down(
438	            policy.as_ref(),
439	            &reason,
440	            same_provider_attempt,
441	            expired,
442	            policy_refused,
443	        ) {
444	            if matches!(terminal, RetryLoopTerminal::Failed(_)) {
445	                record_advisory_exhaustion(seam, request, &reason, attempt).await;
446	            }
447	            return RetryLoopOutcome { attempt, terminal };
448	        }
449	        // The stand-down above returns `Failed` whenever no policy is present,
450	        // so a `None` here is structurally unreachable — kept as the honest
451	        // failure terminal rather than an unwrap.
452	        let Some(policy) = policy.as_ref() else {
453	            return RetryLoopOutcome {
454	                attempt,
455	                terminal: RetryLoopTerminal::Failed(reason),
456	            };
457	        };
458	        // Record the failed attempt durably as a NON-terminal (Retryable)
459	        // `ActivityFailed` — the observable retry record the history cursor
460	        // walks past to the eventual terminal. Recording failures abort the
461	        // loop into an honest terminal failure: an unrecorded retry is a
462	        // silent retry.
463	        match record_retry_event(
464	            seam,
465	            request,
466	            RetryRecord::AttemptFailed {
467	                attempt,
468	                reason: reason.clone(),
469	                kind: aion_core::ActivityErrorKind::Retryable,
470	            },
471	        )
472	        .await
473	        {
474	            RetryRecordOutcome::Recorded => {}
475	            RetryRecordOutcome::Settled => {
476	                return RetryLoopOutcome {
477	                    attempt,
478	                    terminal: RetryLoopTerminal::SettledElsewhere,
479	                };
480	            }
481	            RetryRecordOutcome::EpochClosed => {
482	                return stood_down_on_closed_epoch(request, attempt);
483	            }
484	            RetryRecordOutcome::RecordFailed(record_error) => {
485	                tracing::warn!(
486	                    workflow_id = %request.workflow_id,
487	                    activity_id = %request.activity_id,
488	                    attempt,
489	                    error = %record_error,
490	                    "failed to record a retryable activity failure; failing the activity instead \
491	                     of retrying unrecorded"
492	                );
493	                return RetryLoopOutcome {
494	                    attempt,
495	                    terminal: RetryLoopTerminal::Failed(reason),
496	                };
497	            }
498	        }
499	        announce_and_back_off(policy, request, &reason, same_provider_attempt).await;

