1	use super::{await_support::envelope, support::*};
2	
3	// ---- #197: retry loop at the dispatch seam ------------------------------
4	
5	/// Scripted dispatcher for the retry-loop tests: pops one outcome per
6	/// dispatch and records the wire attempt each delivery carried.
7	pub(in super::super) struct ScriptedRetryDispatcher {
8	    outcomes: std::sync::Mutex<std::collections::VecDeque<Result<String, String>>>,
9	    attempts: std::sync::Mutex<Vec<u32>>,
10	    task_queues: std::sync::Mutex<Vec<String>>,
11	}
12	
13	impl ScriptedRetryDispatcher {
14	    pub(super) fn new(outcomes: Vec<Result<String, String>>) -> Arc<Self> {
15	        Arc::new(Self {
16	            outcomes: std::sync::Mutex::new(outcomes.into_iter().collect()),
17	            attempts: std::sync::Mutex::new(Vec::new()),
18	            task_queues: std::sync::Mutex::new(Vec::new()),
19	        })
20	    }
21	
22	    pub(super) fn seen_attempts(&self) -> Vec<u32> {
23	        self.attempts
24	            .lock()
25	            .map(|attempts| attempts.clone())
26	            .unwrap_or_default()
27	    }
28	
29	    pub(super) fn seen_task_queues(&self) -> Vec<String> {
30	        self.task_queues
31	            .lock()
32	            .map(|queues| queues.clone())
33	            .unwrap_or_default()
34	    }
35	}
36	
37	impl ActivityDispatcher for ScriptedRetryDispatcher {
38	    fn dispatch(&self, request: ActivityDispatch) -> Result<String, String> {
39	        self.attempts
40	            .lock()
41	            .map_err(|_| "attempts lock poisoned".to_owned())?
42	            .push(request.attempt);
43	        self.task_queues
44	            .lock()
45	            .map_err(|_| "task queue lock poisoned".to_owned())?
46	            .push(request.task_queue);
47	        self.outcomes
48	            .lock()
49	            .map_err(|_| "outcomes lock poisoned".to_owned())?
50	            .pop_front()
51	            .ok_or_else(|| "terminal:script exhausted — unexpected extra dispatch".to_owned())?
52	    }
53	}
54	
55	/// Store + recorder + request over a seeded `WorkflowStarted` +
56	/// `ActivityScheduled` + `ActivityStarted(attempt 1)` history — exactly
57	/// what the dispatch NIF records before spawning the completion task.
58	pub(in super::super) struct RetryLoopHarness {
59	    pub(super) store: Arc<dyn EventStore>,
60	    pub(super) seam: RetryRecorderSeam,
61	    pub(super) request: ActivityDispatch,
62	    pub(super) workflow_id: WorkflowId,
63	}
64	
65	impl RetryLoopHarness {
66	    pub(super) async fn seeded(config: &str) -> Result<Self, Box<dyn std::error::Error>> {
67	        let store: Arc<dyn EventStore> = Arc::new(aion_store::InMemoryStore::default());
68	        let workflow_id = WorkflowId::new_v4();
69	        let run_id = RunId::new_v4();
70	        let events = vec![
71	            Event::WorkflowStarted {
72	                envelope: envelope(&workflow_id, 1),
73	                workflow_type: "retrier".to_owned(),
74	                input: Payload::from_json(&json!({}))?,
75	                run_id: run_id.clone(),
76	                parent_run_id: None,
77	                parent_workflow_id: None,
78	                package_version: aion_core::PackageVersion::new("b".repeat(64)),
79	            },
80	            Event::ActivityScheduled {
81	                envelope: envelope(&workflow_id, 2),
82	                activity_id: ActivityId::from_sequence_position(0),
83	                activity_type: "flaky".to_owned(),
84	                input: Payload::new(ContentType::Json, br#""in""#.to_vec()),
85	                task_queue: String::from("default"),
86	                node: None,
87	            },
88	            Event::ActivityStarted {
89	                envelope: envelope(&workflow_id, 3),
90	                activity_id: ActivityId::from_sequence_position(0),
91	                attempt: 1,
92	            },
93	        ];
94	        store
95	            .append(WriteToken::recorder(), &workflow_id, &events, 0)
96	            .await?;
97	        let recorder = Recorder::resume_at(workflow_id.clone(), Arc::clone(&store), 3);
