1	//! End-to-end tests for engine-honored per-activity retry policies (#197).
2	//!
3	//! The packaged `examples/retry-policy` workflow declares an explicit
4	//! `RetryPolicy` (3 total attempts, fixed backoff) on its one remote
5	//! activity and contains NO retry logic of its own. These tests prove, over
6	//! the real engine:
7	//!
8	//! 1. A worker that fails retryably N-1 times and then succeeds costs the
9	//!    run RETRIES, not the run: the workflow Completes, with the whole
10	//!    per-attempt trail recorded (`ActivityFailed` kind `Retryable` per
11	//!    failed attempt, `ActivityStarted` per delivery, terminal at
12	//!    `attempt = N`).
13	//! 2. A worker that exhausts the budget fails the workflow with the LAST
14	//!    reason verbatim and the final attempt count — and that run stays
15	//!    reopenable exactly as before: `reopen_workflow` re-drives the
16	//!    activity live at the NEXT attempt (the trail continues, never
17	//!    restarts) and the reopened run completes.
18	//!
19	//! The archive is rebuilt from the committed example source on every run —
20	//! see `common/example_build.rs` for why this gate must never skip.
21	
22	#[path = "test_support/gleam.rs"]
23	mod gleam_test_support;
24	
25	#[path = "common/example_build.rs"]
26	mod example_build;
27	
28	use std::sync::Arc;
29	use std::sync::atomic::{AtomicU32, Ordering};
30	
31	use aion::EngineBuilder;
32	use aion::activity::bridge::{ActivityDispatch, ActivityDispatcher};
33	use aion_core::{ActivityErrorKind, Event, Payload, WorkflowStatus};
34	use aion_store::{EventStore, InMemoryStore};
35	use serde_json::json;
36	
37	/// Deterministic stand-in for a remote worker whose backing service flakes:
38	/// fails every delivery with a retryable (transient) error until the wire
39	/// attempt reaches `succeed_from_attempt`, then replies normally. Records
40	/// each delivery's wire attempt for assertion.
41	struct FlakyDispatcher {
42	    succeed_from_attempt: u32,
43	    calls: std::sync::Mutex<Vec<u32>>,
44	    deliveries: AtomicU32,
45	}
46	
47	impl FlakyDispatcher {
48	    fn new(succeed_from_attempt: u32) -> Arc<Self> {
49	        Arc::new(Self {
50	            succeed_from_attempt,
51	            calls: std::sync::Mutex::new(Vec::new()),
52	            deliveries: AtomicU32::new(0),
53	        })
54	    }
55	
56	    fn seen_attempts(&self) -> Vec<u32> {
57	        self.calls
58	            .lock()
59	            .map(|calls| calls.clone())
60	            .unwrap_or_default()
61	    }
62	}
63	
64	impl ActivityDispatcher for FlakyDispatcher {
65	    fn dispatch(&self, request: ActivityDispatch) -> Result<String, String> {
66	        if request.name != "flaky_call" {
67	            return Err(format!("terminal:unknown activity {}", request.name));
68	        }
69	        self.deliveries.fetch_add(1, Ordering::SeqCst);
70	        self.calls
71	            .lock()
72	            .map_err(|_| "terminal:calls lock poisoned".to_owned())?
73	            .push(request.attempt);
74	        if request.attempt < self.succeed_from_attempt {
75	            return Err(format!(
76	                "retryable:upstream stream reset (delivery attempt {})",
77	                request.attempt
78	            ));
79	        }
80	        let value: serde_json::Value = serde_json::from_str(&request.input)
81	            .map_err(|error| format!("terminal:bad input: {error}"))?;
82	        let who = value["name"].as_str().unwrap_or("stranger");
83	        Ok(json!({ "reply": format!("steady hello, {who}") }).to_string())
84	    }
85	}
