161	/// module over the reference package's SDK closure.
162	fn direct_package(reference: &Package, entry: &str) -> Result<Package, Box<dyn std::error::Error>> {
163	    let document = parse(SOURCE)?;
164	    let module = lower(&document, None)?;
165	    let direct_bytes = select(&module)?;
166	
167	    let reference_entry = reference
168	        .beams()
169	        .get(entry)
170	        .ok_or_else(|| format!("reference package has no entry beam `{entry}`"))?
171	        .to_vec();
172	    if reference_entry == direct_bytes {
173	        return Err(
174	            "the direct production is byte-identical to the reference entry — \
175	                    the splice would be a no-op"
176	                .into(),
177	        );
178	    }
179	    let mut modules = Vec::new();
180	    for beam in reference.beams().iter() {
181	        if beam.name() == entry {
182	            modules.push(BeamModule::new(entry, direct_bytes.clone()));
183	        } else {
184	            modules.push(BeamModule::new(beam.name(), beam.bytes()));
185	        }
186	    }
187	    let archive = PackageBuilder::new(reference.manifest().clone(), BeamSet::new(modules)?)
188	        .write_to_bytes()?;
189	    let spliced = Package::load_from_bytes(archive, ExtractionLimits::unbounded())?;
190	    let spliced_entry = spliced
191	        .beams()
192	        .get(entry)
193	        .ok_or_else(|| format!("spliced package lost its entry beam `{entry}`"))?;
194	    if spliced_entry != direct_bytes.as_slice() {
195	        return Err("the spliced entry beam is not the direct production".into());
196	    }
197	    Ok(spliced)
198	}
